(1, 'default', 1, 'Home', 'page/home', 'page', 'home', '', '', '', '', '<section class=\"services\">\n\n<div class=\"service-inner\">\n\n<div class=\"container\">\n\n<div class=\"row\">\n\n<div class=\"col-md-4 col-sm-4 service-box\">\n\n<div class=\"service-box-content\">\n\n<h3><a href=\"#\">Scholarship Facility</a></h3>\n\n\n\n<p>Eimply dummy text printing ypese tting industry.</p>\n\n\n\n<div class=\"service-box-icon\"><img src=\"https://demo.smart-school.in/uploads/gallery/media/scholarship-icon.png\" /></div>\n\n</div>\n\n</div>\n\n<!--./col-md-4-->\n\n\n\n<div class=\"col-md-4 col-sm-4 service-box\">\n\n<div class=\"service-box-content\">\n\n<h3><a href=\"#\">Books & Liberary</a></h3>\n\n\n\n<p>Eimply dummy text printing ypese tting industry.</p>\n\n\n\n<div class=\"service-box-icon\"><img src=\"https://demo.smart-school.in/uploads/gallery/media/book-icon.png\" /></div>\n\n</div>\n\n</div>\n\n<!--./col-md-4-->\n\n\n\n<div class=\"col-md-4 col-sm-4 service-box\">\n\n<div class=\"service-box-content\">\n\n<h3><a href=\"#\">Certified Teachers</a></h3>\n\n\n\n<p>Eimply dummy text printing ypese tting industry.</p>\n\n\n\n<div class=\"service-box-icon\"><img src=\"https://demo.smart-school.in/uploads/gallery/media/teacher-icon.png\" /></div>\n\n</div>\n\n</div>\n\n<!--./col-md-4--></div>\n\n</div>\n\n</div>\n\n</section>\n\n\n\n<div class=\"container spacet40\"><!--./row--></div>\n\n<!--./container-->\n\n\n\n<section class=\"bg-gray fullwidth spaceb40 spacet40\">\n\n<div class=\"container\">\n\n<div class=\"row\">\n\n<div class=\"col-md-8 col-sm-12 col-md-offset-2 text-center\">\n\n<h2 class=\"head-title\">ABOUT US</h2>\n\n\n\n<div class=\"divider\">&nbsp;</div>\n\n</div>\n\n\n\n<div class=\"col-md-6 col-sm-6\">\n\n<div class=\"about_img\"><img class=\"img-responsive img-rounded\" src=\"https://demo.smart-school.in/uploads/gallery/media/about.jpg\" /></div>\n\n</div>\n\n<!--./col-md-6-->\n\n\n\n<div class=\"col-md-6 col-sm-6\">\n\n<div class=\"about-right\">\n\n<h