(4, 'default', 0, 'Contact us', 'page/contact-us', 'page', 'contact-us', '', '', '', '', '<section class=\"contact\">\n\n<div class=\"container\">\n\n<div class=\"row\">\n\n<h2 class=\"col-md-12 col-sm-12\">Send In Your Query</h2>\n\n\n\n<p>&nbsp;</p>\n\n\n\n<div class=\"col-md-12 col-sm-12\">[form-builder:contact_us]<!--./row--></div>\n\n<!--./col-md-12--></div>\n\n<!--./row--></div>\n\n<!--./container--></section>\n\n\n\n<div class=\"col-md-4 col-sm-4\">\n\n<div class=\"contact-item\"><img src=\"http://192.168.1.81/repos/smartschool/uploads/gallery/media/pin.svg\" />\n\n<h3>Our Location</h3>\n\n\n\n<p>350 Fifth Avenue, 34th floor New York NY 10118-3299 USA</p>\n\n</div>\n\n<!--./contact-item--></div>\n\n<!--./col-md-4-->\n\n\n\n<div class=\"col-md-4 col-sm-4\">\n\n<div class=\"contact-item\"><img src=\"http://192.168.1.81/repos/smartschool/uploads/gallery/media/phone.svg\" />\n\n<h3>CALL US</h3>\n\n\n\n<p>E-mail : info@abcschool.com</p>\n\n\n\n<p>Mobile : +91-9009987654</p>\n\n</div>\n\n<!--./contact-item--></div>\n\n<!--./col-md-4-->\n\n\n\n<div class=\"col-md-4 col-sm-4\">\n\n<div class=\"contact-item\"><img src=\"http://192.168.1.81/repos/smartschool/uploads/gallery/media/clock.svg\" />\n\n<h3>Working Hours</h3>\n\n\n\n<p>Mon-Fri : 9 am to 5 pm</p>\n\n\n\n<p>Sat : 9 am to 3 pm</p>\n\n</div>\n\n<!--./contact-item--></div>\n\n<!--./col-md-4-->\n\n\n\n<div class=\"col-md-12 col-sm-12\">\n\n<div class=\"mapWrapper fullwidth\"><iframe frameborder=\"0\" height=\"500\" marginheight=\"0\" marginwidth=\"0\" scrolling=\"no\" src=\"http://maps.google.com/maps?f=q&source=s_q&hl=EN&q=time+square&aq=&sll=40.716558,-73.931122&sspn=0.40438,1.056747&ie=UTF8&rq=1&ev=p&split=1&radius=33.22&hq=time+square&hnear=&ll=37.061753,-95.677185&spn=0.438347,0.769043&z=9&output=embed\" width=\"100%\"></iframe></div>\n\n</div>', '0000-00-00', 0, 0, 'no', '2019-05-04 15:46:41'),
(6, 'manual', 0, 'Teacher', 'page/teacher', 'page', 'teacher', '', '', '', '', '<div class=\"container spaceb60 spacet60\">\n\n<div class=\"row\">\n\n<div class=\"col-md-3 col-sm-3\">\n\n<div class=\"staffteam\">\n\n<div class=\"staffteamimg\"><img src=\"https://svnjagiroad.in/jagiimg/rubul.jpg\" />\n\n<ul class=\"social-links\">\n\n	<li>Facebook</li>\n\n	<li>Twitter</li>\n\n	<li>Linkedin</li>\n\n	<li>Google Plus</li>\n\n</ul>\n\n</div>\n\n\n\n<div class=\"staff-content\">\n\n<h3>Rubul Saikia</h3>\n\nPrincipal</div>\n\n</div>\n\n</div>\n\n\n\n<div class=\"col-md-3 col-sm-3\">\n\n<div class=\"staffteam\">\n\n<div class=\"staffteamimg\"><img src=\"https://svnjagiroad.in/jagiimg/3.jpeg\" />\n\n<ul class=\"social-links\">\n\n	<li>Facebook</li>\n\n	<li>Twitter</li>\n\n	<li>Linkedin</li>\n\n	<li>Google Plus</li>\n\n</ul>\n\n</div>\n\n\n\n<div class=\"staff-content\">\n\n<h3>Jyoti Boruah</h3>\n\n<span class=\"post\">Bsc pass</span></div>\n\n</div>\n\n</div>\n\n\n\n<div class=\"col-md-3 col-sm-3\">\n\n<div class=\"staffteam\">\n\n<div class=\"staffteamimg\"><img src=\"https://svnjagiroad.in/jagiimg/2.jpeg\" />\n\n<ul class=\"social-links\">\n\n	<li>Facebook</li>\n\n	<li>Twitter</li>\n\n	<li>Linkedin</li>\n\n	<li>Google Plus</li>\n\n</ul>\n\n</div>\n\n\n\n<div class=\"staff-content\">\n\n<h3>Sangita devnath</h3>\n\n<span class=\"post\">M.A in English</span></div>\n\n</div>\n\n</div>\n\n\n\n<div class=\"col-md-3 col-sm-3\">\n\n<div class=\"staffteam\">\n\n<div class=\"staffteamimg\"><img src=\"https://svnjagiroad.in/jagiimg/1.jpeg\" />\n\n<ul class=\"social-links\">\n\n	<li>Facebook</li>\n\n	<li>Twitter</li>\n\n	<li>Linkedin</li>\n\n	<li>Google Plus</li>\n\n</ul>\n\n</div>\n\n\n\n<div class=\"staff-content\">\n\n<h3>Nabanita bordoloi</h3>\n\n<span class=\"post\">MA English</span></div>\n\n</div>\n\n</div>\n\n\n\n<div class=\"col-md-3 col-sm-3\">\n\n<div class=\"staffteam\">\n\n<div class=\"staffteamimg\"><img src=\"https://svnjagiroad.in/jagiimg/4.jpeg\" />\n\n<ul class=\"social-links\">\n\n	<li>Facebook</li>\n\n	<li>Twitter</li>\n\n	<li>Linkedin</li>\n\n	<li>Google Plus</li>\n\n</ul>\n\n</div>\n\n\n\n<div class=\"staff-content\">\n\n<h3>Chupi teranpi</h3>\n\n<span class=\"post\">Sanskrit BA..deled</span></div>\n\n</div>\n\n</div>\n\n\n\n<div class=\"col-md-3 col-sm-3\">\n\n<div class=\"staffteam\">\n\n<div class=\"staffteamimg\"><img src=\"https://svnjagiroad.in/jagiimg/9.jpeg\" />\n\n<ul class=\"social-links\">\n\n	<li>Facebook</li>\n\n	<li>Twitter</li>\n\n	<li>Linkedin</li>\n\n	<li>Google Plus</li>\n\n</ul>\n\n</div>\n\n\n\n<div class=\"staff-content\">\n\n<h3>Nayanmoni Mishra</h3>\n\n<span class=\"post\">BA honours in Sanskrit</span></div>\n\n</div>\n\n</div>\n\n\n\n<div class=\"col-md-3 col-sm-3\">\n\n<div class=\"staffteam\">\n\n<div class=\"staffteamimg\"><img src=\"https://svnjagiroad.in/jagiimg/10.jpeg\" />\n\n<ul class=\"social-links\">\n\n	<li>Facebook</li>\n\n	<li>Twitter</li>\n\n	<li>Linkedin</li>\n\n	<li>Google Plus</li>\n\n</ul>\n\n</div>\n\n\n\n<div class=\"staff-content\">\n\n<h3>Parag kumar Deka</h3>\n\n<span class=\"post\">Bsc</span></div>\n\n</div>\n\n</div>\n\n\n\n<div class=\"col-md-3 col-sm-3\">\n\n<div class=\"staffteam\">\n\n<div class=\"staffteamimg\"><img alt=\"\" src=\"https://svnjagiroad.in/jagiimg/7.jpeg\" />\n\n<ul class=\"social-links\">\n\n	<li>Facebook</li>\n\n	<li>Twitter</li>\n\n	<li>Linkedin</li>\n\n	<li>Google Plus</li>\n\n</ul>\n\n</div>\n\n\n\n<div class=\"staff-content\">\n\n<h3>Himakshi Bora</h3>\n\n<span class=\"post\">M.A.( Assamese)</span></div>\n\n</div>\n\n</div>\n\n</div>\n\n</div>', '0000-00-00', 0, 0, 'no', '2024-04-03 17:17:23');
